import * as THREE from 'three';
export class Effects {
 constructor(scene){this.scene=scene;this.rings=[];this.particles=[];this.max=320;this.mesh=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(.07,0),new THREE.MeshBasicMaterial({color:0xffffff}),this.max);this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);this.mesh.frustumCulled=false;scene.add(this.mesh);this.dummy=new THREE.Object3D();this.color=new THREE.Color();this.ringGeo=new THREE.RingGeometry(.86,1,40);}
 burst(x,y,z,color=0xffcc77,n=10){for(let i=0;i<n&&this.particles.length<this.max;i++)this.particles.push({x,y,z,vx:(Math.random()-.5)*5,vy:1+Math.random()*4,vz:(Math.random()-.5)*5,life:.4+Math.random()*.5,max:.9,color});}
 ring(x,z,r,color=0xffc56b,duration=.4){const mat=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.7,side:THREE.DoubleSide,depthWrite:false});const m=new THREE.Mesh(this.ringGeo,mat);m.rotation.x=-Math.PI/2;m.position.set(x,.08,z);this.scene.add(m);this.rings.push({mesh:m,r,life:duration,max:duration});return m;}
 update(dt){for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;if(p.life<=0){this.particles.splice(i,1);continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vy-=9*dt;this.dummy.position.set(p.x,Math.max(.06,p.y),p.z);this.dummy.scale.setScalar(Math.min(1,p.life*4));this.dummy.updateMatrix();this.mesh.setMatrixAt(i,this.dummy.matrix);this.mesh.setColorAt(i,this.color.set(p.color));}this.mesh.count=this.particles.length;this.mesh.instanceMatrix.needsUpdate=true;if(this.mesh.instanceColor)this.mesh.instanceColor.needsUpdate=true;for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.life-=dt;if(r.life<=0){this.scene.remove(r.mesh);r.mesh.material.dispose();this.rings.splice(i,1);continue;}const k=1-r.life/r.max;r.mesh.scale.setScalar(r.r*(.4+.6*k));r.mesh.material.opacity=.7*(1-k);}}
 clear(){this.particles.length=0;for(const r of this.rings){this.scene.remove(r.mesh);r.mesh.material.dispose();}this.rings=[];this.mesh.count=0;}
}
